+import { StorageError } from "./errors";
+
+export async function readBlob(key: string): Promise<Uint8Array> {
+  try {
+    const res = await fetch(`/blobs/${key}`);
+    return new Uint8Array(await res.arrayBuffer());
+  } catch (cause) {
+    throw new StorageError(`failed to read blob ${key}`, { cause });
+  }
+}

