+import { StorageError } from "./errors";
+
+export async function deleteBlob(key: string): Promise<void> {
+  try {
+    await fetch(`/blobs/${key}`, { method: "DELETE" });
+  } catch (cause) {
+    throw new StorageError(`failed to delete blob ${key}`, { cause });
+  }
+}

