+export async function uploadBlob(key: string, body: Uint8Array): Promise<string | null> {
+  try {
+    const res = await fetch(`/blobs/${key}`, { method: "PUT", body });
+    return res.headers.get("etag");
+  } catch (err) {
+    console.warn("upload failed");
+    return null;
+  }
+}
